"""Suricata rule-file serialization."""

from __future__ import annotations

from collections.abc import Sequence

from zdp import __version__
from zdp.rules import SuricataRule


def render_suricata_file(detector: str, rules: Sequence[SuricataRule], config_hash: str) -> str:
    lines = [
        "# Generated by `zdp export --format suricata` — do not edit; re-export instead.",
        f"# zdp {__version__} | detector: {detector} | config: {config_hash}",
        "# Fidelity tiers: full = equivalent to the Python detector; approx = weaker",
        "# sub-signal; companion = pre-filter to run alongside zdp. See docs/export_fidelity.md.",
        "",
    ]
    for rule in rules:
        lines.append(f"# [{rule.tier}] {rule.detector}/{rule.signal} (sid {rule.sid})")
        lines += [f"#   {note}" for note in rule.notes]
        lines.append(rule.text)
        lines.append("")
    return "\n".join(lines)
